p='features/claims/useClaims.ts'; s=open(p).read()
s=s.replace("""  proofs: number };""","""  proofs: number;
  /** The number of the claim this one was split off; none when it was not split off one. */
  splitFrom: string | null };""")
open(p,'w').write(s)
p='slots/defs/claimRow.ts'; s=open(p).read()
s=s.replace("proofs?: number };","proofs?: number; splitFrom?: string | null };")
open(p,'w').write(s)
p='features/claims/status.slot.tsx'; s=open(p).read()
s=s.replace("""// in force on its date cannot be settled or approved while it has none (refused before the clerk limit is considered).
""","""// in force on its date cannot be settled or approved while it has none (refused before the clerk limit is considered).
// An OPEN claim (not deferred, not in a closed period) can be split: an amount above 0.00 and below its own goes to a new
// OPEN claim with the next number, listed as the person's newest and showing the claim's number as split-from.
""")
s=s.replace("""  const [deferUntil, setDeferUntil] = useState('');
""","""  const [deferUntil, setDeferUntil] = useState('');
  const [splitAmount, setSplitAmount] = useState('');
""")
s=s.replace("""  // Each action on the claim clears the other's refusal, so one error shows: the last action's.
  const changeTo = (to: Change) => {
    reassign.reset();
    resettle.reset();
    defer.reset();
    proof.reset();
    change.mutate(to);
  };
  const busy = change.isPending || reassign.isPending || resettle.isPending || defer.isPending || proof.isPending;
  const error = change.error ?? reassign.error ?? resettle.error ?? defer.error ?? proof.error;
""","""  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/split`,
        { amount: amount.trim(), by: user ?? '' }),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
  });
  // Each action on the claim clears the other's refusal, so one error shows: the last action's.
  const changeTo = (to: Change) => {
    reassign.reset();
    resettle.reset();
    defer.reset();
    proof.reset();
    split.reset();
    change.mutate(to);
  };
  const busy = change.isPending || reassign.isPending || resettle.isPending || defer.isPending || proof.isPending || split.isPending;
  const error = change.error ?? reassign.error ?? resettle.error ?? defer.error ?? proof.error ?? split.error;
""")
# add split.reset() to the other buttons' handlers
for m in ['reassign.mutate(moveTo);','resettle.mutate();','defer.mutate(deferUntil);','proof.mutate();']:
    s=s.replace("          "+m, "          split.reset();\n          "+m)
s=s.replace("""      {error && (""","""      Split from <span data-testid="claim-split-from">{claim.splitFrom ?? ''}</span>{' '}
      <input
        data-testid="claim-split-amount"
        placeholder="Split amount"
        value={splitAmount}
        onChange={(e) => {
          setSplitAmount(e.target.value);
          split.reset();
        }}
      />
      <button
        type="button"
        data-testid="claim-split"
        disabled={busy}
        onClick={() => {
          change.reset();
          reassign.reset();
          resettle.reset();
          defer.reset();
          proof.reset();
          split.mutate(splitAmount);
        }}
      >
        Split
      </button>{' '}
      {error && (""")
open(p,'w').write(s)
EOF
grep -c "split.reset" features/claims/status.slot.tsx; cd ../../..; bin/e2e 2>&1 | tail -40

